mapper.select:
SELECT authgrp_id AS row_id, authgrp_nm, authgrp_desc, use_yn FROM t_auth_grp WHERE use_yn = 'Y'
AND (authgrp_id LIKE '%' || #{filterKeyword} || '%' OR authgrp_nm LIKE '%' || #{filterKeyword} || '%')
ORDER BY authgrp_id LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE t_auth_grp SET
    authgrp_nm = #{authgrpNm}, authgrp_desc = #{authgrpDesc},
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE authgrp_id = #{rowId}
